import type { PrismaClient, Booking } from './prisma.ts';
export async function makeBooking(db: PrismaClient): Promise<Booking> {
  // id is server-owned — BookingCreateInput does not accept it.
  return db.booking.create({ data: { lab: 'BE-201', seats: 40, id: 1 } });
}

export type Booking = { id: number; lab: string; seats: number; createdAt: string };
export type BookingCreateInput = { lab: string; seats: number };
export interface BookingDelegate {
  create(args: { data: BookingCreateInput }): Promise<Booking>;
  findUnique(args: { where: { id: number } }): Promise<Booking | null>;
}
export type PrismaClient = { booking: BookingDelegate };

import type { PrismaClient } from '../src/prisma.ts';
import { makeBooking } from '../src/repo.ts';
export async function call(db: PrismaClient) { return makeBooking(db); }

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { PrismaClient } from '../src/prisma.ts';
import { makeBooking } from '../src/repo.ts';
const db: PrismaClient = { booking: { create: async ({ data }) => ({ id: 1, lab: data.lab, seats: data.seats, createdAt: 'now' }), findUnique: async () => null } };
test('makeBooking creates with the client fields', async () => { const b = await makeBooking(db); assert.equal(b.lab, 'BE-201'); assert.equal(b.seats, 40); });

