import type { PrismaClient } from './prisma.ts';
export async function seatsOf(db: PrismaClient, id: number): Promise<number> {
  const row = await db.booking.findUnique({ where: { id } });
  // row may be null.
  return row.seats;
}

export type Booking = { id: number; lab: string; seats: number; createdAt: string };
export type BookingCreateInput = { lab: string; seats: number };
export interface BookingDelegate {
  create(args: { data: BookingCreateInput }): Promise<Booking>;
  findUnique(args: { where: { id: number } }): Promise<Booking | null>;
}
export type PrismaClient = { booking: BookingDelegate };

import type { PrismaClient } from '../src/prisma.ts';
import { seatsOf } from '../src/repo.ts';
export async function call(db: PrismaClient) { return seatsOf(db, 1); }

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { PrismaClient } from '../src/prisma.ts';
import { seatsOf } from '../src/repo.ts';
const mk = (found: boolean): PrismaClient => ({ booking: { create: async ({ data }) => ({ id: 1, lab: data.lab, seats: data.seats, createdAt: 'now' }), findUnique: async () => (found ? { id: 1, lab: 'BE-201', seats: 40, createdAt: 'now' } : null) } });
test('missing -> 0, found -> seats', async () => { assert.equal(await seatsOf(mk(false), 1), 0); assert.equal(await seatsOf(mk(true), 1), 40); });

